manifestSources.text:
[package]
name = "harness-browser"
version = "0.1.0"
edition = "2024"
rust-version = "1.99"
publish = false

[dependencies]
base64 = "=0.22.1"
chromiumoxide = { version = "=0.9.1", default-features = false }
futures-util = "0.3"
harness-application = { path = "../application" }
harness-domain = { path = "../domain" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
tokio = { version = "1", features = ["rt-multi-thread", "time", "sync", "net", "io-util", "macros"] }
url = "2"
uuid = { version = "1", features = ["v4"] }

[package]
name = "harness-mcp"
version = "0.8.9"
edition = "2024"
rust-version = "1.99"
publish = false

[dependencies]
harness-application = { path = "../application" }
harness-domain = { path = "../domain", features = ["schema"] }
rmcp = { version = "=3.5.1", default-features = false, features = ["server", "macros"] }
serde_json = "1"
tokio = { version = "1", features = ["macros", "rt-multi-thread", "time", "sync", "io-util"] }

[package]
name = "harness-cli"
version = "0.1.0"
edition = "2024"
rust-version = "1.99"
publish = false

[dependencies]
harness-domain = { path = "../domain" }
harness-application = { path = "../application" }
harness-skills = { path = "../skills" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
futures-util = { version = "0.3", features = ["io"] }
tokio = { version = "1", features = ["macros", "rt-multi-thread", "time", "sync", "io-util", "io-std", "process", "signal"] }
rustyline-async = { path = "../../vendor/rustyline-async" }
termimad = "=0.35.4"
image = { version = "=0.25.8", default-features = false, features = ["bmp", "png"] }

[target.'cfg(windows)'.dependencies]
windows = { version = "=0.62.2", features = ["Win32_Foundation", "Win32_System_DataExchange", "Win32_System_Memory"] }

[dev-dependencies]
regex = "1"
tempfile = "3"

[package]
name = "harness-jobs"
version = "0.1.0"
edition = "2024"
rust-version = "1.99"
publish = false

[dependencies]
harness-application = { path = "../application" }
harness-domain = { path = "../domain", features = ["schema"] }
serde_json = "1"
tokio = { version = "1", features = ["macros", "rt-multi-thread", "time", "sync"] }
uuid = { version = "1", features = ["v4"] }
regex = "1"
rusqlite = { version = "=0.40.2", features = ["bundled", "hooks", "limits"] }

[target.'cfg(unix)'.dependencies]
libc = "0.2"

[target.'cfg(windows)'.dependencies]
windows = { version = "=0.62.2", features = ["Win32_Foundation", "Win32_Storage_FileSystem"] }

[dev-dependencies]
tempfile = "3"
